function rob(nums) {
  let prev = 0, cur = 0;
  for (const x of nums) [prev, cur] = [cur, Math.max(cur, prev + x)];
  return cur;
}
console.log(rob([2, 7, 9, 3, 1]), rob([2, 1, 1, 2]));

function lisTails(a) {
  const tails = [];
  for (const x of a) {
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1; else hi = mid;
    }
    tails[lo] = x;
  }
  return tails;
}
const t = lisTails([3, 10, 2, 1, 20]);
console.log(t.length, t.join(','));

